import { invoke } from "@tauri-apps/api/core";
import { Context, Effect, Layer, Stream } from "effect";
import { parseDslError, type DslError, type DslTask } from "./error";
import { listen } from "@tauri-apps/api/event";

// Convert curly quotes (e.g. auto-generated by macOS smart quotes) into ASCII ones
const normalizeDslText = (text: string): string =>
  text
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'");

export type ServerStatus =
  | "Connecting"
  | "Healthy"
  | "Disconnected"
  | { Degraded: number };

export interface DslClientService {
  readonly setUrl: (url: string) => Effect.Effect<void, DslError>;
  readonly getUrl: Effect.Effect<string, DslError>;
  readonly post: <T = any>(
    endpoint: string,
    body: string,
    source: string,
  ) => Effect.Effect<T, DslError>;
  readonly put: <T = any>(
    endpoint: string,
    body: string,
    source: string,
  ) => Effect.Effect<T, DslError>;
  readonly delete: <T = any>(endpoint: string) => Effect.Effect<T, DslError>;
  readonly getStatus: Effect.Effect<string, DslError>;
  readonly connect: Effect.Effect<void, DslError>;
  readonly getTasks: Effect.Effect<DslTask[], DslError>;
  readonly get: <T = any>(endpoint: string) => Effect.Effect<T, DslError>;
  readonly statusStream: Stream.Stream<ServerStatus, DslError>;
}

export class DslClient extends Context.Tag("DslClient")<
  DslClient,
  DslClientService
>() {}

export const DslClientLive = Layer.succeed(
  DslClient,
  DslClient.of({
    setUrl: (url) =>
      Effect.tryPromise({
        try: () => invoke<void>("set_dsl_url", { url }),
        catch: parseDslError,
      }),

    getUrl: Effect.tryPromise({
      try: () => invoke<string>("get_dsl_url"),
      catch: parseDslError,
    }),

    post: <T = any>(endpoint: string, body: string, source: string) =>
      Effect.gen(function* () {
        const reqId = crypto.randomUUID();

        const postTask = Effect.tryPromise({
          try: () =>
            invoke<T>("post_dsl_endpoint", {
              reqId,
              endpoint,
              body: normalizeDslText(body),
              source,
            }),
          catch: parseDslError,
        });

        return yield* postTask.pipe(
          Effect.onInterrupt(() =>
            Effect.tryPromise({
              try: () => invoke("cancel_dsl_task", { reqId }),
              catch: (e) => console.error("Failed to cancel Dsl POST task", e),
            }).pipe(Effect.ignore),
          ),
        );
      }),

    put: <T = any>(endpoint: string, body: string, source: string) =>
      Effect.gen(function* () {
        const reqId = crypto.randomUUID();

        const putTask = Effect.tryPromise({
          try: () =>
            invoke<T>("put_dsl_endpoint", {
              reqId,
              endpoint,
              body: normalizeDslText(body),
              source,
            }),
          catch: parseDslError,
        });

        return yield* putTask.pipe(
          Effect.onInterrupt(() =>
            Effect.tryPromise({
              try: () => invoke("cancel_dsl_task", { reqId }),
              catch: (e) => console.error("Failed to cancel Dsl PUT task", e),
            }).pipe(Effect.ignore),
          ),
        );
      }),

    delete: <T = any>(endpoint: string) =>
      Effect.gen(function* () {
        const reqId = crypto.randomUUID();

        const deleteTask = Effect.tryPromise({
          try: () => invoke<T>("delete_dsl_endpoint", { reqId, endpoint }),
          catch: parseDslError,
        });

        return yield* deleteTask.pipe(
          Effect.onInterrupt(() =>
            Effect.tryPromise({
              try: () => invoke("cancel_dsl_task", { reqId }),
              catch: (e) =>
                console.error("Failed to cancel Dsl DELETE task", e),
            }).pipe(Effect.ignore),
          ),
        );
      }),

    getStatus: Effect.tryPromise({
      try: () => invoke<string>("get_dsl_status"),
      catch: parseDslError,
    }),

    connect: Effect.tryPromise({
      try: () => invoke<void>("connect_dsl"),
      catch: parseDslError,
    }),

    getTasks: Effect.tryPromise({
      try: () => invoke<DslTask[]>("get_dsl_tasks"),
      catch: parseDslError,
    }),

    get: <T = any>(endpoint: string) =>
      Effect.gen(function* () {
        const reqId = crypto.randomUUID();

        const getTask = Effect.tryPromise({
          try: () => invoke<T>("get_dsl_endpoint", { reqId, endpoint }),
          catch: parseDslError,
        });

        return yield* getTask.pipe(
          Effect.onInterrupt(() =>
            Effect.tryPromise({
              try: () => invoke("cancel_dsl_task", { reqId }),
              catch: (e) => console.error("Failed to cancel Dsl GET task", e),
            }).pipe(Effect.ignore),
          ),
        );
      }),

    statusStream: Stream.async<ServerStatus, DslError>((emit) => {
      invoke<ServerStatus>("get_dsl_status")
        .then((s) => emit.single(s))
        .catch((e) => emit.fail(parseDslError(e)));

      const unlistenPromise = listen<ServerStatus>(
        "dsl-status-update",
        (event) => {
          emit.single(event.payload);
        },
      );

      return Effect.promise(async () => {
        const unlisten = await unlistenPromise;
        unlisten();
      });
    }),
  }),
);
